data.staticInitializer:
z
  .object({
    qid: z.string(),
    /** 提问的 actor，`site@ordinal` 形态。 */
    actor: z.string(),
    /** 该 actor 的人类可读名；匿名 actor 缺席（读侧自己决定怎么渲染「无名」）。 */
    actorName: z.string().optional(),
    question: z.string(),
    context: z.string().optional(),
    /** 提问时刻（epoch ms，与 createdAt / updatedAt 同一把尺）。 */
    askedAt: z.number(),
  })
  .strict()

z
  .object({
    id: z.string(),
    kind: z.enum(["file", "markdown", "chart", "table", "metrics", "board"]),
    /** 卡片标题；脚本没给时缺席（facade 的默认标题就是 id）。 */
    title: z.string().optional(),
    /** 最新版号。 */
    version: z.number(),
    /** 内容产物的 MIME；预置看板缺席。 */
    contentType: z.string().optional(),
    /** 内容产物最新版的字节数；预置看板缺席。 */
    bytes: z.number().optional(),
    /** 内容产物的工作区出处（字节已拷进 store，这只是「它原本在哪」）。 */
    sourcePath: z.string().optional(),
    /** 预置看板收到的标签 `report` 条数；内容产物恒 0。 */
    itemCount: z.number(),
    /** run 的交付物（至多一件），排在清单最前。 */
    primary: z.literal(true).optional(),
  })
  .strict()

z.object({
  runId: z.string().min(1),
  /** 已烹熟的展示标签（name → 脚本首行 → runId 由服务侧派生）。 */
  label: z.string(),
  /** `"name"` = 用户起的名字；`"script"` = 读时从脚本派生（含 runId 兜底）。 */
  labelSource: z.enum(["name", "script"]),
  status: z.enum(WORKFLOW_RUN_LIFECYCLE_STATUSES),
  /** `status === "stopped"` 才在场。 */
  stopReason: z.enum(WORKFLOW_RUN_STOP_REASONS).optional(),
  /** 本 run 修订自哪个 run（`dwf_run.resumed_from`）；不是修订则缺席。 */
  resumedFrom: z.string().min(1).optional(),
  /** 本 run 被哪次修订停下并替代（`stopped(superseded)` 的结算袋）；未被替代则缺席。 */
  supersededBy: z.string().min(1).optional(),
  ownedByThisSession: z.boolean(),
  /** 「本会话无法证实它还活着」的标注，为真时才在场。绝不是状态改写。 */
  possiblyInterrupted: z.boolean().optional(),
  /** epoch ms（journal 的 time_created / time_updated）。 */
  createdAt: z.number(),
  updatedAt: z.number(),
})
